using System;using System.Linq;using System.Text;using System.Reflection;using Verse;using Verse.AI;using Verse.AI.Group;using RimWorld;using PlayableRecreation;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.ToList())if(w.GetType().Name.Contains("Faction")||w.GetType().Name.Contains("MiniGame"))w.Close(false);Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;TogetherMatch.Reset();TogetherInvite.Reset();var map=Find.CurrentMap;Host.State["map"]=map;Host.State["chess"]=map.listerThings.AllThings.First(t=>t.ThingID=="ChessTable66193");var pair=new Pawn[3];for(int i=0;i<3;i++){var p=PawnGenerator.GeneratePawn(PawnKindDefOf.Colonist,Faction.OfPlayer);p.Name=new NameSingle("R2 Tester "+i);GenSpawn.Spawn(p,new IntVec3(149+i,0,117),map);p.needs.food.CurLevelPercentage=1;p.needs.rest.CurLevelPercentage=1;p.needs.joy.CurLevelPercentage=.3f;for(int h=0;h<24;h++)p.timetable.SetAssignment(h,TimeAssignmentDefOf.Anything);pair[i]=p;}Host.State["pair"]=pair;Host.State["rostra"]=pair[0];Host.State["anya"]=pair[1];Host.State["ineligible"]=pair[2];var guest=map.mapPawns.AllPawnsSpawned.First(p=>p.LabelShort=="QA Visitor");Host.State["guest"]=guest;PRMod.Settings.immersionMode=true;PRMod.Settings.playTogether=true;PRMod.Settings.saveSessions=true;PRMod.Settings.pauseWhilePlaying=false;PRMod.Settings.playTogetherVisitors=true;PRMod.Settings.playTogetherInvites=true;foreach(var g in DefDatabase<MiniGameDef>.AllDefsListForReading)PRMod.Settings.SetEnabled(g,true);var sb=new StringBuilder();sb.AppendLine("assembly="+typeof(Together).Assembly.Location+" module="+typeof(Together).Module.ModuleVersionId+" process="+System.Diagnostics.Process.GetCurrentProcess().Id);sb.AppendLine("map="+map+" guest="+guest+" Lord="+guest.GetLord()?.LordJob+" joy="+guest.needs.joy);foreach(var def in DefDatabase<MiniGameDef>.AllDefsListForReading)sb.AppendLine(def.defName+" seats="+Together.SeatCount(def)+" applies="+Together.AppliesTo(def));return sb.ToString();}}
